import {modules} from './curriculum.mjs';
import {mountBike} from './bike-3d.mjs';
import {createWorkshop,workshopAct,workshopScore,workshopState,faults} from './workshop-model.mjs';
const $=s=>document.querySelector(s),all=modules.flatMap(m=>m.lessons.map(l=>({...l,module:m.id,moduleTitle:m.title}))),key='mecanica.bikes.v1';let saved={completed:[],passed:[],workshops:[]},storageWarning='';try{const x=JSON.parse(localStorage.getItem(key)||'null');if(x&&Array.isArray(x.completed)&&Array.isArray(x.passed)&&Array.isArray(x.workshops))saved=x;}catch{storageWarning='El progreso no se pudo recuperar en este navegador.';}
function save(){try{localStorage.setItem(key,JSON.stringify(saved));}catch{storageWarning='El progreso se conserva solo durante esta sesión.';}renderProgress();}
const tools=['Lupa, cinta métrica y cuaderno','Llaves del tamaño correcto, dinamométrica y bandejas','Cepillos suaves, paños y herramientas de inspección','Medidor de cadena, tronchacadenas y alicate compatibles','Llaves, cortacables y manual del freno','Manual del cáliper, herramientas y medidores especificados','Bomba con manómetro y desmontables compatibles','Herramientas y manual del cambio','Centrador, tensiómetro y llaves según tarea','Herramienta de biela y eje específica','Llaves y dinamométrica apropiadas','Manual de suspensión y bomba específica si corresponde','Ficha de diagnóstico y herramientas de medición','Referencias exactas, calibre y tablas de compatibilidad','Manual del sistema y observación externa','Ficha de trabajo, manuales y lista de control'];
const parts={frame:['Cuadro','Los triángulos conectan ruedas, pedales y apoyos. Inspecciona uniones y zonas de sujeción; la pintura puede ocultar daños.'],chain:['Cadena','Las articulaciones transmiten tracción entre plato y piñón. El retorno se simplifica en este banco: no reproduce el recorrido real por las roldanas.'],crank:['Bielas y plato','La biela convierte fuerza del pedal en torque. El plato del modelo tiene 32 dientes.'],cassette:['Cassette','Un piñón mayor reduce vueltas de rueda por pedalada. La torre de coronas representa distintas relaciones.'],brake:['Freno mecánico','La guaya mueve una pastilla hacia el rotor; la opuesta queda fija en este esquema. Explora holgura, alineación y fricción en el taller.'],front:['Rueda delantera','Neumático, rin, radios, buje y rotor. La válvula y los radios permiten reconocer el giro. El freno actúa sobre esta rueda.'],rear:['Rueda trasera','Recibe el torque de la transmisión. El banco representa acoplamiento directo al pedalear, sin simular la rueda libre.'],fork:['Horquilla','Conecta dirección y rueda. Las barras y botellas muestran la estructura de una horquilla de suspensión; su amortiguación interna no se simula aquí.'],steering:['Dirección y manubrio','La potencia fija el manubrio a la horquilla. Precarga del rodamiento y fijación de potencia tienen funciones distintas.'],saddle:['Sillín y tija','Apoyan al ciclista. Respeta marcas de inserción y límites de sujeción.'],derailleur:['Cambio trasero','Guía la cadena entre piñones y recoge longitud. La jaula y las roldanas se identifican en el despiece.'],stand:['Soporte','Mantiene la bicicleta suspendida para observar su funcionamiento. En una bici real usa puntos de sujeción autorizados.']};
const focusByModule=['frame','crank','frame','chain','brake','brake','front','cassette','rear','crank','steering','fork','chain','cassette','crank','frame'];let selected=all.find(l=>l.id===new URL(location.href).searchParams.get('lesson'))||all[0],workshop=null,playing=false,exploded=false;
const bench=mountBike($('#viewport'),selectPart);
function selectPart(id){if(!parts[id])return;bench.select(id);$('#partInfo').textContent=parts[id].join(' · ');for(const b of $('#parts').children)b.setAttribute('aria-pressed',String(b.dataset.part===id));}
for(const [id,[label]]of Object.entries(parts)){const b=document.createElement('button');b.textContent=label;b.dataset.part=id;b.onclick=()=>selectPart(id);$('#parts').append(b);}
function renderProgress(){$('#progress').textContent=saved.completed.filter(id=>all.some(l=>l.id===id)).length+' / 87 lecciones completadas'+(storageWarning?' · '+storageWarning:'');}
function renderNav(){const root=$('#syllabus');root.replaceChildren();const query=$('#search').value.toLocaleLowerCase('es');for(const m of modules){const list=m.lessons.filter(l=>(l.title+' '+m.title+' '+l.id).toLocaleLowerCase('es').includes(query));if(!list.length)continue;const d=document.createElement('details');d.open=!!query||m.id===selected.module;const summary=document.createElement('summary');summary.textContent=String(m.id).padStart(2,'0')+' · '+m.title;d.append(summary);for(const l of list){const b=document.createElement('button');b.textContent=(saved.completed.includes(l.id)?'✓ ':'')+l.id+' · '+l.title;b.setAttribute('aria-current',String(selected.id===l.id));b.onclick=()=>choose(l.id);d.append(b);}root.append(d);}if(!root.children.length)root.textContent='No hay lecciones con ese término.';renderProgress();}
function choose(id){selected=all.find(l=>l.id===id)||all[0];const url=new URL(location.href);url.searchParams.set('lesson',selected.id);url.hash='curso';history.replaceState(null,'',url);renderLesson();renderNav();selectPart(focusByModule[selected.module-1]);$('#lesson').focus({preventScroll:true});}
function el(tag,text,parent){const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;}
function renderLesson(){const root=$('#lesson');root.replaceChildren();const l=selected;el('p','MÓDULO '+l.module+' / '+l.moduleTitle,root).className='lesson-kicker';el('h2',l.id+' · '+l.title,root);el('p',l.theory,root).className='theory';const visual=el('a','Explorar las piezas de esta lección en 3D ↓',root);visual.href='#banco';visual.onclick=()=>selectPart(focusByModule[l.module-1]);
 const practical=el('section','',root);practical.className='lesson-box';el('h3','Taller práctico',practical);el('p','Prepara: '+tools[l.module-1]+'.',practical);const ol=el('ol','',practical);l.steps.forEach(s=>el('li',s+'.',ol));el('p','Antes de intervenir: identifica la referencia del componente y consulta su manual. Al terminar, registra qué comprobaste y qué cambió.',practical).className='caption';
 const diagnosis=el('section','',root);diagnosis.className='diagnosis';el('h3','Piensa como mecánico',diagnosis);el('p',l.diagnosis,diagnosis);
 const quiz=el('section','',root);quiz.className='lesson-box quiz';el('h3','Comprueba lo aprendido',quiz);el('p',l.question,quiz);const result=el('p',saved.passed.includes(l.id)?'Respuesta correcta guardada. Puedes repasar la pregunta.':'Elige una respuesta y justifica tu decisión con la teoría.',quiz);result.dataset.result='';result.setAttribute('role','status');const offset=all.indexOf(l)%3;for(let i=0;i<3;i++){const answer=(i+offset)%3,b=el('button',l.answers[answer],quiz);b.dataset.answer=answer;b.onclick=()=>{if(answer===l.correct){if(!saved.passed.includes(l.id))saved.passed.push(l.id);save();result.textContent='Correcto. '+l.answers[l.correct]+'. '+l.theory;complete.disabled=false;}else result.textContent='Todavía no. Revisa la explicación y vuelve a intentar. '+l.diagnosis;};}
 const complete=el('button',saved.completed.includes(l.id)?'Lección completada ✓':'Marcar lección completada',root);complete.disabled=!saved.passed.includes(l.id);complete.className='complete';complete.onclick=()=>{if(!saved.completed.includes(l.id))saved.completed.push(l.id);save();renderNav();complete.textContent='Lección completada ✓';};const nav=el('div','',root);nav.className='lesson-nav';const index=all.indexOf(l);for(const [label,n]of [['← Anterior',index-1],['Siguiente →',index+1]]){const b=el('button',label,nav);b.disabled=n<0||n>=all.length;b.onclick=()=>choose(all[n].id);}if([4,5,6].includes(l.module)){const a=el('a','Practicar cadena y frenos en el taller →',root);a.href='#taller';}}
$('#search').oninput=renderNav;
function syncBench(){const gear=+$('#gear').value,cadence=+$('#cadence').value,brake=+$('#brake').value;const f=workshop?workshopState(workshop):{};bench.set({gear,cadence,brake,faults:f});$('#cadenceValue').value=cadence+' rpm';$('#readout').textContent='Relación ideal 32/'+gear+' = '+(32/gear).toFixed(2)+' · Rueda trasera sin averías: '+(cadence*32/gear).toFixed(0)+' rpm · '+(workshop?'Taller activo: observa continuidad, articulación y respuesta del freno.':'Banco sin fallos.');}
for(const id of ['gear','cadence','brake'])$('#'+id).oninput=syncBench;
$('#play').onclick=()=>{playing=!playing;bench.play(playing);$('#play').textContent=playing?'Pausar movimiento':'Iniciar movimiento';$('#play').setAttribute('aria-pressed',String(playing));};$('#explode').onclick=()=>{exploded=!exploded;bench.explode(exploded);$('#explode').textContent=exploded?'Ensamblar':'Despiece';$('#explode').setAttribute('aria-pressed',String(exploded));};$('#resetView').onclick=()=>bench.reset();$('#focusPart').onclick=()=>bench.focus();
function act(action,id){workshopAct(workshop,action,id);if(workshop.done&&!saved.workshops.some(r=>r.id===workshop.id)){saved.workshops.push({id:workshop.id,date:new Date().toISOString(),score:workshopScore(workshop),mode:workshop.mode,errors:workshop.errors,hints:workshop.hints});saved.workshops=saved.workshops.slice(-30);save();}syncBench();renderWorkshop();}
function renderWorkshop(){const root=$('#workshop');root.replaceChildren();if(!workshop){el('p','Empieza guiado para practicar una cadena abierta y un cable con holgura. En sorpresa recibirás una avería de cadena y otra de freno, sin revelar sus nombres hasta resolverlas.',root);}else{el('h3',workshop.mode==='guided'?'Taller guiado · unión de cadena y ajuste de freno':'Caso sorpresa · descubre las dos averías',root);el('p',workshopScore(workshop)+'/100 · '+workshop.errors+' decisiones incorrectas · '+workshop.hints+' pistas',root).className='score';el('p','Cada intervención innecesaria o verificación fallida resta 15; cada pista, 10. Inspeccionar no resta. Este ejercicio no sustituye comprobar la bici real.',root);if(workshop.mode==='guided'){const ol=el('ol','',root);['Inspecciona la cadena: busca continuidad, cierre y articulación.','Confirma compatibilidad de la unión y elige su reparación.','Inspecciona el freno mecánico: guaya, holgura, centrado y fricción.','Elige el ajuste que corresponde al síntoma.','Comprueba ambos sistemas: resolver solo uno no completa el taller.'].forEach(t=>el('li',t,ol));}
 const grid=el('div','',root);grid.className='workshop-grid';for(const system of ['chain','brake']){const card=el('div','',grid);card.className='workshop-card';el('h3',system==='chain'?'01 / Cadena':'02 / Freno mecánico',card);const inspect=el('button','Inspeccionar '+(system==='chain'?'cadena':'freno'),card);inspect.dataset.inspect=system;inspect.disabled=workshop.done;inspect.onclick=()=>{selectPart(system==='chain'?'chain':'brake');bench.focus();act('inspect',system);};for(const [id,f]of Object.entries(faults).filter(([,f])=>f.system===system)){const b=el('button',f.repair,card);b.dataset.repair=id;b.disabled=workshop.done||!workshop.inspected.includes(system)||workshop.fixed.includes(id);b.onclick=()=>act('repair',id);}el('a','Mirar en 3D ↑',card).href='#banco';}
 if(workshop.feedback)el('p',workshop.feedback,root).className='feedback';const actions=el('div','',root);actions.className='buttons';const h=el('button','Pedir pista (−10)',actions);h.disabled=workshop.done||workshop.hintUsed;h.onclick=()=>act('hint');const v=el('button','Comprobar ambos sistemas',actions);v.dataset.verify='';v.disabled=workshop.done;v.onclick=()=>act('verify');if(workshop.done){el('h3','Caso resuelto · '+workshopScore(workshop)+'/100',root);workshop.faults.forEach(id=>{el('h4',faults[id].label,root);el('p',faults[id].explain,root);});el('p','Registro guardado. Prueba otro caso sorpresa para distinguir síntomas parecidos.',root);}}
 if(saved.workshops.length){el('h3','Tus últimos talleres',root);const ul=el('ul','',root);saved.workshops.slice(-5).reverse().forEach(r=>el('li',new Date(r.date).toLocaleDateString('es-CO')+' · '+(r.mode==='guided'?'Guiado':'Sorpresa')+' · '+r.score+'/100 · '+r.errors+' errores · '+r.hints+' pistas',ul));}}
function start(mode){workshop=createWorkshop(mode);syncBench();renderWorkshop();selectPart('chain');}
$('#guided').onclick=()=>start('guided');$('#surprise').onclick=()=>start('surprise');$('#healthy').onclick=()=>{workshop=null;syncBench();renderWorkshop();};
renderNav();renderLesson();selectPart('frame');syncBench();renderWorkshop();window.bikeDebug=()=>({selected:selected.id,saved,workshop,bench:bench.debug?.()});
